     */
    public function run()
    {
          DB::unprepared(
                  "INSERT INTO `our_teams` (`id`, `name`, `designation`, `description`, `category`, `image_link`, `preference`, `linkedin`, `created_at`, `updated_at`) VALUES
                  (3, 'Sahely Ganguly', 'PRODUCT CONSULTANT', 'Sahely Ganguly is an M.Phil in Clinical Psychology and registered with Rehabilitation Council of India. She is known for her incomparable skills in building awareness about mental health wellness through publications and digital media. The fusion of her expertise in the field of Psychology and her interest in reaching masses through digital mediums has led her to join hands with HappiMynd, as a founding team member.\r\n                    She has an experience of over a decade in psychometric assessment and psychotherapy, which brings a lot of value to our platform. Her experience supports the foundation of HappiMynd’s vision, mission and beliefs.', 'Experts', '1630081122-sahely_ganguly.png', 4, NULL, '2021-08-27 16:18:43', '2021-08-28 09:35:22'),
                  (4, 'Harbhajan Singh', 'Strategic Advisor', 'Mr. Singh is an industry visionary and a veteran from the Human Resource field, with 45+ years of diverse industry experience. He is Chief of Strategy and HR at XLRI Delhi. Also, presently he is the Chairman of Ease of Doing Business, CII Haryana & President of Federation of Indian Industry, Haryana Chapter. He had been a part of multiple Central & State Govt. Business Expert Delegations. Extremely passionate about the welfare of employees and an advocate of employee care, his guidance will be instrumental for understanding employee issues on the ground and creating services that will help in serving grass root level.', 'Experts', '1630081228-harbhajan_singh.png', 2, NULL, '2021-08-27 16:20:28', '2021-08-28 09:35:22'),
                  (5, 'PS Murthy', 'Strategic Advisor', 'Shri PS Murthy served in the Government of Andhra Pradesh, as Joint Director - IT & Communications Department. He also served in the Ministry of Finance/Ministry of Home Affairs, Govt. of India & AP State Public Sector Undertakings. He was instrumental in getting global IT giants to India. He is well acquainted with administrative rules, regulations, procedures and processes, establishment, personnel & HR matters of Government & PSUs, IT Industry Promotion, e-Governance, Digital & Social Media. He is passionate about extending the benefits of Emotional wellbeing to the Government & IT establishment which has been his Karmabhumi. His guidance will be instrumental for HappiMynd in forging partnerships in these sectors.', 'Experts', '1630081321-ps_murthy.png', 1, NULL, '2021-08-27 16:22:02', '2021-08-28 09:35:22'),
                  (6, 'Rahuul Patil', 'Strategic Advisor', 'Rahuul is the Global Director of Revenue & Operations, Euro T20 Slam. He has been the CEO of North East United FC, CEO of Chennaiyin FC & Business Head – Sports at WIZCRAFT International Entertainment. He has immense expertise in organizing Professional Football Club and International Cricket Tournaments. Rahuul cares deeply for the psychological well-being of players in the field of Sports & has been championing the cause. His mission to bring awareness and prevention of emotional and mental health issues in budding sportsmen brought him near to HappiMynd. We look forward to engaging the youth of India in the most important factor of overall well being through his guidance.', 'Experts', '1630081382-rahuul_patil.png', 3, NULL, '2021-08-27 16:23:02', '2021-08-28 09:35:22'),
                  (7, 'Amit Rathi', 'Founder', 'An alumnus of IIM-C and a member of ISB – CEE, Amit Rathi is also the founder of HappiMynd. He is passionate about uplifting life quality of the people in India and comes from an extensive corporate background. The amalgamation of his passion and experience has resulted in the establishment of HappiMynd.\r\n                    Through HappiMynd, Amit visions to engage, empower and involve people in protecting their mental wellness as a part of their overall well-being. He wishes that the platform reaches masses so that people from all walks of life can manage their mental wellness with ease and without the fear of judgment. Bringing this ground breaking approach to remove stigma and inertia against mental health issues, is his biggest motivation.', 'Founders', '1630081769-amit_rathi.png', 2, 'https://www.linkedin.com/in/amit-rathi-iimc/', '2021-08-27 16:29:29', '2021-08-28 11:39:38'),
                  (8, 'Dr Neeraj Tripathi', 'CO-FOUNDER', 'Dr. Neeraj Tripathi is a Member of the Royal College of Psychiatrists and MBBS from India. He is trained in psychological interventions and is a practitioner of advanced techniques. He is motivated to bring global best practices in the field of mental wellness to India. Hence, he joined hands to establish HappiMynd as a Co -Founder. It is his universal approach that adds more value to our platform by matching the global industry standards.\r\n                    He is also a co-founder of a rehabilitation home in London and extremely passionate in serving the society through his work. He is also pursuing an executive MBA from Warwick Business School.', 'Founders', '1630092178-neeraj_tripathi.png', 3, 'https://www.linkedin.com/in/dr-neeraj-tripathi-95119bb3/', '2021-08-27 16:37:59', '2021-08-28 11:39:38'),
                  (9, 'Ravi Kant Suman', 'CO-FOUNDER', 'Ravi has developed strong business acumen and proficiency in general management. He is an expert in account handling, content strategy, and learning and development function. His enthusiasm for improving the standards of the work environment, in terms of efficiency, job satisfaction and happiness quotient led him to the path of establishing HappiMynd as a Co-Founder.\r\n                    Ravi believes that happy people lead to happy work culture and happy work culture leads to efficiency, job satisfaction and increased retention rates.  He believes that everyone should be empowered, informed and actively involved in managing their mental wellness throughout their lifespan with the help of digital technology.', 'Founders', '1630082349-ravi_kant.png', 1, 'https://www.linkedin.com/in/ravi-kant-suman-4261a816/', '2021-08-27 16:39:10', '2021-08-28 11:39:38'),
                  (15, 'Dr. Geetha Challa', 'Counselling Psychologist', 'Dr. Geetha Challa holds a PhD. & has done her Masters in Counselling\r\n                    Psychology. She is a practising psychologist with more than 25 years of\r\n                    experience and is licensed by the Rehabilitation Council of India (RCI). She is an\r\n                    Internationally certified REBT and CBT therapist from Albert Ellis Institute New\r\n                    York. She has expertise in therapies like CBT, REBT, MetaCognitive Therapy,\r\n                    SFBT, NLP, Movement Therapy etc.\r\n                    Dr. Geetha is doing some substantial work with government and non-\r\n                    government departments and educational institutions. She also does extensive\r\n                    work in Counselor Training & Development. With her exceptional knowledge in the field, she will be\r\n                    guiding HappiMynd on needed products for various segments of society.', 'Psychologists', '1630143454-geetha_challa.jpg', 2, NULL, '2021-08-28 09:37:45', '2021-08-28 11:15:52'),
                  (16, 'Kusuma Harish', 'Counselling Psychologist', 'Kusuma has completed her Master’s in Counselling Psychology and Post Graduate Diploma in Learning Disability. She has over 22 years of experience working with all age groups and has expertise in Psychological evaluation, diagnostics, and therapeutic interventions. She is specialized in child guidance and trained in the sexual health of adolescents, work-related stress, couple counselling and family therapy. She has conducted workshops on various topics such as Stress Management, Work-life Balance, Bettering your Communication Skills, Personality Development, Smoking Cessation, etc.\r\n                    Kusuma brings a client-focused approach and helps them analyze the root cause of their problem and approaches to resolve them while maintaining utmost confidentiality which makes her an ideal associate with HappiMynd.', 'Psychologists', '1630144003-kusuma_harish.jpg', 3, NULL, '2021-08-28 09:46:44', '2021-08-28 11:15:52'),
                  (17, 'Aradhana Kaul Kathju', 'Counselling Psychologist', 'Aradhana Kaul Kathju is a certified Psychologist, Psychotherapist, Rehabilitation Counsellor, Special Educator and Corporate Trainer with close to 2 decades of work experience. She has worked with multiple industries pan India. She has expertise in multiple modalities such as REBT, DBT, CBT, REE, Colour Therapy, Graphology, NLP, Psychotherapy for children, adolescents and adults.\r\n                    She conducts regular workshops for children, parents (especially mothers), caregivers and aspirants in the field of psychology. Aradhana’s approach to counselling is client-centric and insightful. Approachability, integrity, discipline and honesty are some of her strongest virtues which makes her an ideal associate at HappiMynd.', 'Psychologists', '1630144053-aradhana_kaul_kathju.jpg', 4, NULL, '2021-08-28 09:47:35', '2021-08-28 11:15:52'),
                  (18, 'Sayli Sovani', 'Psychologist (Clinical)', 'Sayli has a Masters degree in Clinical Psychology and has diverse experience of working in the field of mental wellness for 13+ years. Her efficiency has resulted in a robust experience as a counselor for clinical as well as non-clinical issues. She has worked with individuals and groups of different age ranges.\r\n                    She has experience in parental guidance, adolescent counseling, relationship issues, counseling for critical illnesses, LGBTQAI etc. Her core thought matches the motive of HappiMynd that every person is capable of finding their own answers and can heal themselves; they just need some guidance.', 'Psychologists', '1630144182-sayli_sovani.png', 5, NULL, '2021-08-28 09:49:43', '2021-08-28 11:15:52'),
                  (19, 'Aditi Korgaonkar', 'Counselling Psychologist', 'Aditi has a PhD from the University of Mumbai and also Masters in Counselling Psychology from SNDT Women’s University, Mumbai. She has completed various other courses in the field of psychology that brings a lot of value to HappiMynd. She’s an expert in Art Therapy, Clinical Music Therapy, Counselling Skills, Learning Disabilities and Statistics using R. She has experience of over 11 years of working with many well-established institutions as a counsellor.\r\n                    Her approach conforms to our motive of not limiting ourselves to traditional ways of therapy and counselling. Her key interest areas are personality psychology, career mentoring, counselling and mental health.', 'Psychologists', '1630144304-aditi_kargaonkar.jpeg', 6, NULL, '2021-08-28 09:51:45', '2021-08-28 11:15:52'),
                  (20, 'Noreen Chaudhary', 'Clinical Psychologist', 'Noreen has done M.Phil in Clinical Psychology (Gold Medalist) and is licensed by the Rehabilitation Council of India (RCI). She is also a member of the American Psychological Association. She has an experience of over 10 years in clinical psychology. Her passion and expertise in non-judgmental and sensitive listening make her an ideal associate at HappiMynd.\r\n                    She makes sure to understand the inexplicable feelings that her clients experience through a collaborative process of information gathering with the help of HappiMynd and providing psychotherapeutic intervention. Her beliefs align with our goal to make our users feel better, happier and satisfied in their life.', 'Psychologists', '1630144375-noreen_choudhary.jpeg', 7, NULL, '2021-08-28 09:52:56', '2021-08-28 11:15:52'),
                  (21, 'Payel Chakraborty', 'Psychologist (Clinical)', 'Payel has completed her Masters in Clinical Psychology. She is a Certified Cognitive Behavioral Therapist and Career Counselor. She has over ten years of experience in handling cases of depression, anxiety, personality disorders, stress, eating disorders, couple and marriage counselling, substance abuse, domestic abuse, self-harm among others across all developmental ages. She has counselled & mentored many underprivileged children in various NGOs in Mumbai.\r\n                    Payel uses techniques mainly from CBT, Mindfulness, Emotional Freedom Therapy (EFT), Art Therapy, Rational Emotive Behaviour Therapy (REBT), Motivational interviewing and transactional analysis (TA). In synergy with HappiMynd, she aims to maintain a collaborative and therapeutic alliance with all her clients giving confidentiality, respect, and commitment the utmost priority.', 'Psychologists', '1630144452-payel_chakraborty.png', 8, NULL, '2021-08-28 09:54:27', '2021-08-28 11:15:52'),
                  (22, 'Varsha Dhamenia Tejyan', 'Counselling Psychologist', 'Varsha has done her Masters in Counselling Psychology and Postgraduate\r\n                    Diploma in Guidance and Counselling. She has over 9 years of experience\r\n                    working with NGOs, various projects under the Ministry of Women and child\r\n                    affairs India, leading educational institutions and Corporates. Her expertise\r\n                    lies in Trauma and Grief Counselling, Suicidal and self-harm counselling,\r\n                    Family and Couple Counselling, Infertility related counselling and LGBTQ\r\n                    Supporting counselling. She is trained in CBT, REBT and Family Therapy. She is\r\n                    also a trained infertility counsellor from Manas India.\r\n                    In collaboration with HappiMynd, Varsha aims to help people develop a\r\n                    healthy perception and thought process so they can live their life with more strength and\r\n                    confidence.', 'Psychologists', '1630144524-varsha_dhamenia_tejyan.jpg', 9, NULL, '2021-08-28 09:55:39', '2021-08-28 11:15:52'),
                  (23, 'Jyoti Glory Bernard', 'Clinical Psychologist Associate', 'Jyoti has done Professional Diploma in Clinical Psychology and is licensed by the Rehabilitation Council of India (RCI). She has over 7 years of experience. She has dealt with the emotional and behavioural issues of children, adolescents, adults, and geriatric age groups. She is well equipped with psychometric assessments and psychotherapy. She has expertise in Acceptance Commitment Therapy, Cognitive Behavioural Therapy, Dialectical Behaviour Therapy and Psychodrama.\r\n                    Jyoti has facilitated different educational and mental health awareness workshops in colleges and other organizations. Her critical thinking and complex problem-solving skills to help determine the best course of action for patient care bring a lot of value to HappiMynd.', 'Psychologists', '1630144631-jyoti_glory_bernard.jpg', 10, NULL, '2021-08-28 09:57:11', '2021-08-28 11:15:52'),
                  (24, 'Shrenika Hatarote', 'Clinical Psychologist', 'Shrenika has done M.Phil in Clinical Psychology and is licensed by the Rehabilitation Council of India (RCI). She has been working in the field of Mental Health for the last 6 years. She has experience in handling patients with depression, anxiety, thought distortions, interpersonal issues, adjustment problems and childhood disorders etc. She is well versed with psychological assessment in both children and adults.\r\n                    Shrenika masters in therapeutic interventions like cognitive behaviour therapy, interpersonal therapy, marital therapy, family therapy, and social skill training. Her expertise in working with all age groups with empathy and unconditional positive regard makes her a great fit for HappiMynd.', 'Psychologists', '1630144692-shrenika_hatarote.png', 11, NULL, '2021-08-28 09:58:13', '2021-08-28 11:15:52'),
                  (25, 'Pooja Varma', 'Psychologist (Clinical)', 'Pooja has completed her Masters in Clinical Psychology and is currently pursuing a Ph.D. in Positive Psychology. She has experience working with people of all age groups, gender, culture and diverse ethnic backgrounds for conditions like stress, anxiety, fear, depressive symptoms, troubling emotions, sleep issues, obsessive & compulsive thoughts and past trauma.\r\n                    She integrates techniques of client-centric therapy, solution-focused therapy, positive psychotherapy and psycho-education to provide a healthy and safe space for emotional expression and overall subjective well-being for better personal and professional growth. Her belief that happiness is not just the absence of pain, but the maximization of mental well-being makes her an excellent fit for HappiMynd.', 'Psychologists', '1630144745-pooja_varma.jpeg', 12, NULL, '2021-08-28 09:59:07', '2021-08-28 11:15:52'),
                  (26, 'Veena Nair', 'Clinical Psychologist', 'Veena has done M.Phil in Clinical Psychology and is licensed by the Rehabilitation Council of India (RCI). She has over 5 years of experience working in hospitals and conducting training in mental health organizations. Her experience varies from working with adolescents having emotional and academic challenges, psycho-social concerns of geriatric patients as well as adults suffering from relationship issues, suicidal ideations / non-suicidal self-harm, mood disorders, personality disorders, addiction disorders, depression, panic and anxiety. She is also comfortable with grief counselling as well as addressing existential concerns gripping individuals today.\r\n                    Her experience and skills make her an excellent fit at HappiMynd.', 'Psychologists', '1630146451-veena_nair.jpg', 13, NULL, '2021-08-28 10:27:31', '2021-08-28 11:15:52'),
                  (27, 'Urja Dhagia', 'Psychologist (Clinical)', 'Urja has completed her Masters in Clinical Psychology. She has a certification in Hypnotherapy and NLP from the Institute of Clinical Hypnosis And Related Sciences (ICHARS), Mumbai. She has over 5 years of experience in working with emotional wellness ventures. She is well equipped with psychometric assessments and psychotherapy. She has effectively handled many clients with suicidal ideations.\r\n                    Her vision aligns with the vision of HappiMynd, which is to help people reach a state of wellbeing that is comprehensive and long-lasting.', 'Psychologists', '1630146535-urja_dhagia.jpg', 14, NULL, '2021-08-28 10:28:08', '2021-08-28 11:15:52'),
                  (28, 'Malavika Prakki', 'Counselling Psychologist', 'Malavika Prakki has done her Masters in Counselling Psychology and is a certified Neurolinguistic Programming Practitioner, a Happiness Life Coach, Master Mindfulness Practitioner, REBT Life Coach, and an Internationally Certified Green belt & Global Career Coach. She has over 5 years of experience working with children and adults.\r\n                    She shows her expertise in the areas of Work-Life balance, Self-esteem, Motivation, Career confusion, Workplace conflict Resolution, Anger Management, Exam Support, Dealing with Procrastination, Goal Setting, Body Image issues, Weight management, Family-Marital issues, Time Management, etc. With strong interpersonal, organizational and analytical skills, Malavika hopes to put these skills into action to improve mental wellness in collaboration with HappiMynd.', 'Psychologists', '1630146614-malavika_prakki.jpg', 15, NULL, '2021-08-28 10:30:15', '2021-08-28 11:15:52'),
                  (29, 'Akhila Kakeri', 'Psychologist (Clinical)', 'Akhila has completed her Masters in Clinical Psychology. She has experience\r\n                    of over 5 years of dealing with a broad spectrum of mental health issues\r\n                    ranging from lifestyle problems, stress, suicidal behaviour, mood and\r\n                    personality disorders. She has also been continuously involved in supervising\r\n                    and teaching budding counsellors in the field.\r\n                    Akhila is trained in various basic and advanced modes of therapy, which help\r\n                    her fit and tailor the best approach needed for a client. She specializes in\r\n                    adolescent, young adult and adult counselling and is an LGBT ally. Her\r\n                    dedication makes her an ideal associate at HappiMynd.', 'Psychologists', '1630146693-akhila_kakeri.png', 16, NULL, '2021-08-28 10:31:34', '2021-08-28 11:15:52'),
                  (30, 'Sanika Dharaskar', 'Psychologist (Clinical)', 'Sanika has completed her Masters in Clinical Psychology and is currently pursuing an MPhil in Psychology. She is a certified Cognitive Behaviour Therapist and Transactional Analyst Practitioner. She has over 5 years of experience in working at hospitals, NGOs, and schools. Her areas of expertise include Anxiety/Stress/Phobias, Chronic Pain Management, Depression, Addiction, Children and Women Issues, Interpersonal Conflicts, Parenting Difficulties, Relationship Difficulties, Peri/Post-Natal Anxiety & Depression (Mums/Dads), Adjustment Difficulties and Grief. She has experience in counselling HIV and AIDS patients as well.\r\n                    Sanika has been featured numerous times in – Times Group and Moms first club sharing her inputs on Mental and Psychological Wellness. Her passion and experience make her a great fit for HappiMynd.', 'Psychologists', '1630146748-sanika_dharaskar.png', 17, NULL, '2021-08-28 10:32:29', '2021-08-28 11:15:52'),
                  (31, 'Vidhi Naik', 'Counselling Psychologist', 'Vidhi has done masters in Mental Health Counseling from Adelphi University, New York. She has also done short term courses on Autism Spectrum Disorders and Basic Listening Skills. She is proficient in Cognitive Behaviour Therapy through which she helps clients deal with issues related to stress, anxiety, depression and relationships concerns. She has also volunteered for Samaritans Suicide Prevention.\r\n                    Her approach is to observe the person holistically with the help of various tools available on our platform. Vidhi and HappiMynd work in synergy to help the clients achieve serenity and balance in life.', 'Psychologists', '1630146919-vidhi_jain.jpg', 18, NULL, '2021-08-28 10:35:19', '2021-08-28 11:15:52'),
                  (32, 'Sana Panagar', 'Psychologist (Clinical)', 'Sana is a qualified Expressive Arts Therapist and has a Master’s Degree in Clinical Psychology. She has worked as a psychologist with eminent emotional wellness ventures like Masina Hospital, Drishti, Felicity, etc. She has experience of over 4 years. Her vision aligns with the vision of HappiMynd, which is to help people reach a state of wellbeing that is comprehensive and long-lasting. She is well equipped with psychometric assessments and psychotherapy.\r\n                    Sana has versatile experience as she has worked with children, adolescents and adults in both school and hospital settings. Her experience and skills make her an excellent fit at HappiMynd.', 'Psychologists', '1630147151-sana_panagar.png', 19, NULL, '2021-08-28 10:39:12', '2021-08-28 11:15:52'),
                  (33, 'Priyanjali Paul', 'Clinical Psychologist', 'Priyanjali has done M.Phil in Clinical Psychology and is licensed by the Rehabilitation Council of India (RCI). She is currently pursuing her PhD in Psychology (specialization in Neuropsychology) as a UGC Senior Research Fellow from Christ (Deemed to be University), Bangalore. She has an experience of over 4 years of working with various age groups in hospitals and on other platforms. She is certified in Psychological First Aid and Suicide Prevention.\r\n                    Her focus on maximizing space, confidentiality and comfort in the therapeutic relationship, thereby promoting self-exploration which can lead to symptom relief and personal growth brings a lot of value to HappiMynd.', 'Psychologists', '1630147207-priyanjali_paul.png', 20, NULL, '2021-08-28 10:40:08', '2021-08-28 11:15:52'),
                  (34, 'Jill Chheda', 'Psychologist (Clinical)', 'Jill has completed her Masters in Clinical Psychology and has been trained in Transactional Analysis and Gestalt work. She has worked as a consultant psychologist with eminent emotional wellness ventures.  She has experience of over 4 years of working with individuals and all age groups.\r\n                    Jill believes acceptance is one of the greatest strengths an individual can possess. Once you accept what you feel, the process of healing begins. Her belief that when people are provided with a non-judgemental environment and unconditional positive regard, they start to accept themselves the way they are, which makes her an ideal associate at HappiMynd.', 'Psychologists', '1630147258-jill_chheda.png', 21, NULL, '2021-08-28 10:40:59', '2021-08-28 11:15:52'),
                  (35, 'Naina Seth', 'Clinical Psychologist', 'Naina has done M.Phil in Clinical Psychology and is licensed by the Rehabilitation Council of India (RCI). She uses an eclectic approach to therapy for helping clients with anxiety, depression, relationship issues, family issues, marital issues, low self-worth or self-esteem and emotional regulation difficulties. She is also experienced in handling stress related to the workplace or interpersonal space.\r\n                    Naina has a solution-focused approach and challenging work always excites her. Her determination to use her skills to provide emotional well-being and help individuals to be a better version of themselves makes her an ideal associate at HappiMynd.', 'Psychologists', '1630147481-naina_seth.jpg', 22, NULL, '2021-08-28 10:44:42', '2021-08-28 11:15:52'),
                  (36, 'Anushree Kadam', 'Psychologist (Clinical)', 'Anushree has completed her Masters in Clinical Psychology. She has over 4 years of experience working with varied age groups in hospitals, clinics, corporates and online platforms. Her area of expertise includes dealing with interpersonal issues, existential crisis, burn out and work stress, mood disorders, trauma, anxiety, and grief counselling. She is a believer of “one approach does not fit everyone” and has a holistic as well as an integrative approach with therapy modalities.\r\n                    Through HappiMynd, she hopes to provide a safe and secure therapeutic space that would facilitate the process of healing for her clients and help them open up in a non-judgmental and non-threatening environment.', 'Psychologists', '1630147533-anushree_kadam.jpg', 23, NULL, '2021-08-28 10:45:33', '2021-08-28 11:15:52'),
                  (37, 'Kruttikka Sindhkar', 'Psychologist (Clinical)', 'Kruttikka has completed her Masters in Clinical Psychology. She holds a total of over 4 years of work experience and has received training in RE-CBT, CBT, Narrative and Art therapies but prefers using an integrative and eclectic approach in her therapy space. She works with difficulties and issues of varying severity in adults and children. She is also actively involved in providing COVID-19 related mental health support to individuals.\r\n                    Kruttikka also facilitates mental health awareness and conducts workshops. Being a humanist and a passionate psychologist, she hopes to provide empowerment and positive transformation through psychological intervention to her clients through HappiMynd.', 'Psychologists', '1630147602-kruttikka_sindhkar.jpg', 24, NULL, '2021-08-28 10:46:43', '2021-08-28 11:15:52'),
                  (38, 'Richa Gidwani', 'Psychologist (Clinical)', 'Richa has completed her Masters in Clinical Psychology. She has experience of over 4 years of working with diverse groups of individuals from children and adolescents to adults. Her areas of speciality in therapy include depression, anxiety spectrum disorders, stress-related problems, and psychosomatic difficulties. Her therapeutic work is based on modalities like cognitive behaviour therapy, mindfulness practices, and body-based practices.\r\n                    Richa, being a very enthusiastic learner, is currently training to be a creative movement therapy facilitator. She has also conducted several workshops on journaling, meditation, online summer camps for children in the times of COVID, and mental wellbeing awareness. Her dedication makes her an ideal associate at HappiMynd.', 'Psychologists', '1630147673-richa_gidwani.png', 25, NULL, '2021-08-28 10:47:54', '2021-08-28 11:15:52'),
                  (39, 'Lincy Benny', 'Clinical Psychologist', 'Lincy has done M.Phil in Clinical Psychology and is licensed by the Rehabilitation Council of India (RCI). She is well equipped with psychometric assessments and psychotherapy and has dealt with children, adolescents and adults. She has experience in providing therapeutic interventions for various psychiatric disorders, EAP Counselling, clients who have undergone trauma, relationship and family therapy, addiction and the queer community.\r\n                    In synergy with HappiMynd, she hopes to provide a safe and secure therapeutic space that would facilitate the process of healing for her clients and help them open up in a non-judgmental and non-threatening environment.', 'Psychologists', '1630147745-lincy_benny.jpg', 26, NULL, '2021-08-28 10:49:07', '2021-08-28 11:15:52'),
                  (40, 'Sreekutty', 'Counselling Psychologist', 'Sreekutty has done her Masters in Counselling Psychology. She has worked with adolescents, adults and the geriatric population in various settings like schools, colleges and hospitals. She has experience working with issues ranging from depression, stress, anxiety, phobias, OCD, various types of addictions, adjustment, self-esteem and work-life balance. Her approach is eclectic, where she incorporates humanistic, cognitive behaviour therapy and dialectical behaviour therapy.\r\n                    Sreekutty has also conducted workshops on stress management, anger management, self-esteem, leadership and team building, job satisfaction, career development and various positive psychology topics. In synergy with HappiMynd, she hopes to help clients to have an in-depth exploration of their concerns and help them to build insight.', 'Psychologists', '1630147801-sreekutty.jpg', 27, NULL, '2021-08-28 10:50:01', '2021-08-28 11:15:52'),
                  (41, 'Veena Mehta', 'Psychologist (Clinical)', 'Veena has completed her Masters in Clinical Psychology. She has over 4 years of\r\n                    experience working with hospitals and mental health institutes. She has dealt with a\r\n                    wide range of psychological problems, including depression, anxiety, substance\r\n                    abuse, physical and sexual traumas and psychotic disorders. She incorporates\r\n                    cognitive-behavioural therapy, client-centred therapy and play therapy to treat a\r\n                    wide range of psychological problems.\r\n                    Veena is well equipped with psychometric assessments and psychotherapy and has\r\n                    dealt with children, adolescents and adults. Her deep interest in using psychological\r\n                    tools effectively in healing our minds and promoting our life towards wellness makes her an\r\n                    excellent fit for HappiMynd.', 'Psychologists', '1630147879-veena_mehta.jpg', 28, NULL, '2021-08-28 10:51:20', '2021-08-28 11:15:52'),
                  (42, 'Ms. Samanvithaa Adiseshan', 'Clinical Psychologist', 'Samanvithaa has done M.Phil in Clinical Psychology and is licensed by the\r\n                    Rehabilitation Council of India (RCI). She has 5 years of experience dealing with\r\n                    children, adolescents, parents, and adults (both online and in-person). She has\r\n                    worked with cancer patients and their caregivers, as well. She is trained in ACT\r\n                    (Acceptance and Commitment Therapy), Cognitive Behaviour Therapy (CBT),\r\n                    Behaviour Therapy (BT), Rational Emotive Behaviour Therapy (REBT), Solution\r\n                    Focused Brief Therapy (SFBT), Art based therapies, etc.\r\n                    In synergy with HappiMynd, Samanvithaa is driven to empathize and help people\r\n                    out when they&#39;re distressed. She is sincere and strictly follows ethics during\r\n                    practice.', 'Psychologists', '1630147936-samanvithaa_adiseshan.jpg', 29, NULL, '2021-08-28 10:52:17', '2021-08-28 11:15:52'),
                  (43, 'Alankritha', 'Clinical Psychologist', 'Alankritha has done M.Phil in Clinical Psychology and is licensed by the Rehabilitation Council of\r\n                    India (RCI). She has over 4 years of experience and has dealt with anxiety, depression, Personality\r\n                    disorder, Post Traumatic stress disorder (PTSD), Obsessive-Compulsive spectrum disorders, De-\r\n                    addiction and other behavioural disturbances, Psychosomatic conditions, Sleep disturbance, Stress\r\n                    management, Pain management and Interpersonal Relationship problems. She is proficient in the\r\n                    delivery of a wide range of psychotherapies like Cognitive Behaviour Therapy (CBT), Exposure\r\n                    Response Prevention Therapy (ERP), Dialectical Behavioural Therapy (DBT), Relaxation Techniques,\r\n                    Cognitive Rehabilitation Therapy (CRT) and Behaviour modification in children.\r\n                    Alankritha is well equipped with Psychometric assessments, Psychotherapies,\r\n                    Neuropsychological evaluation and Cognitive Rehabilitation. Her versatile experience and expertise\r\n                    make her an excellent fit for HappiMynd.', 'Psychologists', '1630147997-alankritha.jpg', 31, NULL, '2021-08-28 10:53:18', '2021-08-28 11:15:52'),
                  (44, 'Abhilasha Agarwal', 'Clinical Psychologist', 'Abhilasha has done M.Phil in Clinical Psychology and is licensed by the Rehabilitation Council of India (RCI). She is currently pursuing a Ph.d. in Psychology. Her expertise lies in dealing with cases of anxiety, depression, panic attacks, phobias, personality disorder, OCD, adjustment issues and relationship issues. She has also handled children with developmental disorders like Autism, ADHD, Intellectual issues and learning difficulties.\r\n                    Abhilasha uses therapeutic approaches like CBT, MBCT, Relaxation Technique and MET amongst others. She is also skilled in conducting seminars, conferences, online webinars and other training programs. With the help of HappiMynd, she hopes to help individuals on their journey to mental wellness.', 'Psychologists', '1630148064-abhilasha_agarwal.png', 32, NULL, '2021-08-28 10:54:25', '2021-08-28 11:15:52'),
                  (45, 'Sakshi Jain', 'Psychologist (Clinical)', 'Sakshi has completed her Masters in Clinical Psychology and is a certified RECBT therapist. She has experience of over 3 years in psychological testing, assessment and psychotherapy. She has worked with all age groups in settings like schools, clinics, and NGO. She works with her clients in a non-judgmental and feedback oriented manner to identify their inner strengths so that they can develop effective coping skills. Along with providing therapy services, she is actively engaged in creating awareness about mental health.\r\n                    Working in synergy with HappiMynd, she aims at helping her clients march through their journeys of emotional and mental well-being', 'Psychologists', '1630148127-sakshi_jain.jpg', 30, NULL, '2021-08-28 10:55:32', '2021-08-28 11:15:52'),
                  (46, 'Rutuparna Meher', 'Counselling Psychologist', 'Rutuparna has completed her Master’s in Counselling Psychology along with a Diploma in professional counselling course specializing in marriage and family counselling. She has over 3 years of experience working with all age groups in different setups like school, college, corporate sector and Healthcare company.\r\n                    Using a client-centred approach, she has handled psychological issues, relationship issues, study-related issues, problem-solving and decision making issues, geriatric counselling, life stressors and conflicts. Her dedication and enthusiasm make her an ideal associate at HappiMynd.', 'Psychologists', '1630148872-rutuparna_meher.jpg', 1, NULL, '2021-08-28 11:05:24', '2021-08-28 11:15:52');"

            );
      }
}
